import{_ as a,c as t,o as n,ag as r}from"./chunks/framework.ARG558ZT.js";const h=JSON.parse('{"title":"Verified Evidence Spans and Citation Boundaries — practice","description":"","frontmatter":{},"headers":[],"relativePath":"practice/applied-ai/chapters/retrieval-context.md","filePath":"practice/applied-ai/chapters/retrieval-context.md"}'),i={name:"practice/applied-ai/chapters/retrieval-context.md"};function c(o,e,s,d,p,l){return n(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="verified-evidence-spans-and-citation-boundaries-—-practice" tabindex="-1">Verified Evidence Spans and Citation Boundaries — practice <a class="header-anchor" href="#verified-evidence-spans-and-citation-boundaries-—-practice" aria-label="Permalink to “Verified Evidence Spans and Citation Boundaries — practice”">​</a></h1><p><strong>Learner status: still required.</strong> These requirements were separated from the textbook. Use the <a href="./../">integrated sequence</a> and shared evidence record; running reference checks is not independent completion.</p><p><a href="./../../../python-for-ai/retrieval-context.html">Textbook</a></p><h2 id="practice-and-acceptance" tabindex="-1">Practice and acceptance <a class="header-anchor" href="#practice-and-acceptance" aria-label="Permalink to “Practice and acceptance”">​</a></h2><p>Read a two-section note with one cross-boundary fact and one code/table example. Compare baseline line chunks with structure-aware chunks, recording lost context, duplicated evidence and actual model-token counts. Reconstruct each retained citation from its immutable source version and exact locator/span. Simulate a source edit and a permission revocation between search and fetch; neither old private text nor a stale citation may reach the answer.</p><p>Add a genuine but irrelevant quote supporting an incorrect answer and demonstrate why mechanical validation passes while semantic evaluation must fail. Test empty/unknown/duplicate citations, invented quotations, wrong source/extractor versions, Unicode span boundaries, insufficient-evidence output and a user opening a citation after access changes. Preserve a recoverable job state for source/transport outages rather than report an invented factual conclusion.</p><p><strong>Acceptance:</strong> strict checks/tests pass; every published citation resolves to supplied authorized evidence at the checked source version; no-evidence and malformed-answer cases remain distinct; unsupported semantic claims are assessed separately from schema/quote membership. Real generation, durable versioned storage, token-aware structure chunker, browser citation UI, ongoing authorization/deletion lifecycle and learner practice remain unperformed. This lesson provides the intermediate provenance/citation contract and chunk-design reasoning, not a complete production RAG service.</p>',7)])])}const m=a(i,[["render",c]]);export{h as __pageData,m as default};
